 private void subscribe(String media,java.util.function.Consumer<List<MediaBrowser.MediaItem>> callback){final int token=generation;MediaBrowser.SubscriptionCallback sub=new MediaBrowser.SubscriptionCallback(){public void onChildrenLoaded(String p,List<MediaBrowser.MediaItem> list){if(token==generation)callback.accept(list==null?Collections.emptyList():list);}public void onError(String p){if(token==generation)status.setText("Could not load music. Check sign-in and network.");}};MediaBrowser.SubscriptionCallback old=subscriptions.put(media,sub);if(old!=null)browser.unsubscribe(media,old);browser.subscribe(media,sub);}
