 private void dock(){suppressAutoPip=true;updatePip();if(!Settings.canDrawOverlays(this)){pendingDock=true;try{startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}catch(Exception e){pendingDock=false;Toast.makeText(this,"This TV does not expose overlay settings",1).show();}return;}TvPlaybackService.start(this,TvPlaybackService.DOCK);startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 private boolean playing(){return controller!=null&&controller.getPlaybackState()!=null&&controller.getPlaybackState().getState()==PlaybackState.STATE_PLAYING;}
 private boolean pipSupported(){return supportsPip;}
 private void updatePip(){if(!supportsPip)return;int key=(playing()?1:0)|(autoPip?2:0)|(suppressAutoPip?4:0);if(key==lastPipConfig)return;try{setPictureInPictureParams(pipParams());lastPipConfig=key;}catch(IllegalStateException ignored){}}
 private PictureInPictureParams pipParams(){PictureInPictureParams.Builder b=new PictureInPictureParams.Builder().setAspectRatio(new Rational(16,9));if(Build.VERSION.SDK_INT>=31)b.setAutoEnterEnabled(autoPip&&!suppressAutoPip&&playing());ArrayList<RemoteAction> actions=new ArrayList<>();for(String s:new String[]{TvPlaybackService.PREVIOUS,TvPlaybackService.TOGGLE,TvPlaybackService.NEXT})actions.add(TvPlaybackService.remoteAction(this,s));return b.setActions(actions).build();}
